"""Slow, obviously-correct reference for the discovery/calibration stages."""
import itertools
from fractions import Fraction
from math import isqrt


def real_prefix(values):
    out = []
    for v in values:
        if v == 1514:
            break
        out.append(v)
    return out


def fragments_of(release):
    width = release['width']
    out = []
    for row_index, row in enumerate(release['discovery']):
        values = row['values']
        prefix = real_prefix(values)
        acts = row['activation'][:len(prefix)]
        n = len(prefix)
        if n < 2:
            continue
        mean = sum(acts) / n
        var = sum((a - mean) ** 2 for a in acts) / n
        thr = mean + var ** 0.5
        high = [a > thr for a in acts]
        i = 0
        while i < n:
            if not high[i]:
                i += 1
                continue
            j = i
            while j < n and high[j]:
                j += 1
            runlen = j - i
            if runlen >= 2:
                if runlen <= width:
                    start = i
                else:
                    best = None
                    beststart = i
                    for k in range(i, j - width + 1):
                        s = sum(acts[k:k + width])
                        if best is None or s > best:
                            best = s
                            beststart = k
                    start = beststart
                out.append({'row': row_index, 'start': start, 'length': runlen,
                            'class': row['class'],
                            'sequence': tuple(values[start:start + runlen])})
            i = j
    return out


def dist(a, b):
    L = len(a)
    total = 0
    equal = 0
    for x, y in zip(a, b):
        d = abs(x - y)
        if (x < 1514 < y) or (y < 1514 < x):
            d += 1000
        total += d * d
        if x == y:
            equal += 1
    return (total / L) ** 0.5 * (3 / 5) ** equal


def clusters_of(frags, eps, ratio):
    n = len(frags)
    byclass = {}
    for i, f in enumerate(frags):
        byclass.setdefault(f['class'], []).append(i)
    density = {}
    for cls, idx in byclass.items():
        density[cls] = max(2, -(-len(idx) * ratio.numerator // ratio.denominator))
    groups = {}
    for i, f in enumerate(frags):
        groups.setdefault((f['class'], len(f['sequence'])), []).append(i)
    clusters = []
    noise = set(range(n))
    for key in sorted(groups):
        cls, L = key
        idx = groups[key]
        adj = {}
        for a in range(len(idx)):
            for b in range(len(idx)):
                if dist(frags[idx[a]]['sequence'], frags[idx[b]]['sequence']) <= eps:
                    adj.setdefault(a, set()).add(b)
        core = {a for a in range(len(idx)) if len(adj.get(a, ())) >= density[cls]}
        # components of core graph
        comp = {}
        cid = 0
        for a in sorted(core):
            if a in comp:
                continue
            stack = [a]
            comp[a] = cid
            while stack:
                node = stack.pop()
                for other in adj.get(node, ()):
                    if other in core and other not in comp:
                        comp[other] = cid
                        stack.append(other)
            cid += 1
        members = {c: set(v for v in comp if comp[v] == c) for c in comp}
        # attach noncore
        for a in range(len(idx)):
            if a in core:
                continue
            cands = [comp[b] for b in adj.get(a, ()) if b in comp]
            if cands:
                best = min(cands, key=lambda c: min(idx[v] for v in members[c]))
                members[best].add(a)
        for c, mem in members.items():
            globals_ = sorted(idx[v] for v in mem)
            core_globals = sorted(idx[v] for v in mem if v in core)
            noise -= set(globals_)
            clusters.append({'id': min(idx[v] for v in mem if v in core), 'class': cls,
                             'members': globals_, 'core': core_globals})
    clusters.sort(key=lambda c: c['id'])
    return clusters, sorted(noise)


def range_of(frags, cluster):
    seqs = [frags[i]['sequence'] for i in cluster['members']]
    n = len(seqs)
    L = len(seqs[0])
    bounds = []
    for pos in range(L):
        vals = [s[pos] for s in seqs]
        lo = min(vals)
        hi = max(vals)
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        sigma = var ** 0.5
        low = int(lo - sigma)  # trunc toward zero
        high = int(hi + sigma)
        if lo - sigma < 0:
            low = int(lo - sigma)  # python int() truncates toward zero
        bounds.append([max(0, low), min(3028, high)])
    return bounds


def matches(bounds, values):
    prefix = real_prefix(values)
    L = len(bounds)
    if len(prefix) < L:
        return False
    for s in range(len(prefix) - L + 1):
        if all(bounds[i][0] <= prefix[s + i] <= bounds[i][1] for i in range(L)):
            return True
    return False


def calibrate_ref(clusters, release, bounds_by_id):
    classes = release['classes']
    N = [0] * classes
    for row in release['validation']:
        N[row['class']] += 1
    thr = Fraction(release['threshold'][0], release['threshold'][1])
    for c in clusters:
        b = bounds_by_id[c['id']]
        hits = [0] * classes
        for row in release['validation']:
            if matches(b, row['values']):
                hits[row['class']] += 1
        t = c['class']
        inner = Fraction(hits[t], N[t])
        outer = Fraction(0)
        for j in range(classes):
            if j == t:
                continue
            v = Fraction(hits[j], N[j])
            if v > outer:
                outer = v
        score = inner / (outer + Fraction(1, 10000))
        c['hits'] = hits
        c['score'] = score
        c['kept'] = score > thr


def exact_entries_ref(clusters, bounds_by_id, capacity):
    tables = {}
    for c in clusters:
        if not c['kept']:
            continue
        L = len(bounds_by_id[c['id']])
        for key in itertools.product(*[range(bounds_by_id[c['id']][i][0], bounds_by_id[c['id']][i][1] + 1)
                                       for i in range(L)]):
            if 1514 in key:
                continue
            tables.setdefault(L, set()).add(key)
    total = sum(len(v) for v in tables.values())
    return min(total, capacity + 1)
